/*
 * fb_help.h — localized, color-aware `fastboot --help` renderer.
 *
 * Not an AOSP file: MeowArchMobile glue. Renders the help text from the row
 * table generated by scripts/gen-help-entries.py (transcribed from upstream
 * show_help(), guaranteed byte-identical in English). Layout matches upstream
 * exactly: 1-space indent, command column padded to 28, description at 29.
 *
 * Long commands overflow the column and put the description on the next
 * line, as upstream does. Colors: sections bold, commands cyan, dim
 * continuation — only when fbcolor::Enabled().
 */
#pragma once

namespace fbhelp {

// Print the full help text to stdout. Returns 0 (a Main() return value).
int ShowHelp();

}  // namespace fbhelp
